package main

import (
	"errors"
	"fmt"
)

type Config struct {
	Name string
	Port int
}

// ChainError 让 %+v 打出底层错误
type ChainError struct {
	Msg string
	Err error
}

func (e *ChainError) Error() string { return e.Msg }

func (e *ChainError) Format(s fmt.State, verb rune) {
	fmt.Fprint(s, e.Msg)
	if s.Flag('+') && e.Err != nil {
		fmt.Fprintf(s, "\n底层错误: %v", e.Err)
	}
}

func main() {
	cfg := Config{Name: "api", Port: 8080}
	fmt.Printf("%v\n", cfg)  // {api 8080}
	fmt.Printf("%+v\n", cfg) // {Name:api Port:8080}

	err := &ChainError{Msg: "保存配置失败", Err: errors.New("磁盘只读")}
	fmt.Printf("%v\n", err)  // 保存配置失败
	fmt.Printf("%+v\n", err) // 保存配置失败 + 底层错误: 磁盘只读
}

package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("用户不存在")

type ValidationError struct {
	Field  string
	Reason string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("字段 %s 不合法: %s", e.Field, e.Reason)
}

type User struct {
	Name string
	Age  int
}

func findUser(id int) error {
	if id == 0 {
		return fmt.Errorf("查找用户 %d 失败: %w", id, ErrNotFound)
	}
	return nil
}

func validate(name string) error {
	if name == "" {
		return &ValidationError{Field: "name", Reason: "不能为空"}
	}
	return nil
}

func main() {
	// 哨兵错误 + errors.Is
	err := findUser(0)
	fmt.Println("错误信息:", err)
	fmt.Println("是「用户不存在」吗?", errors.Is(err, ErrNotFound))

	// 自定义错误类型 + errors.As
	var ve *ValidationError
	if errors.As(validate(""), &ve) {
		fmt.Printf("出错的字段: %s（原因: %v）\n", ve.Field, ve.Reason)
	}

	// 拆开一层错误链
	fmt.Println("拆开后:", errors.Unwrap(err))

	// 多个错误合成一个
	joined := errors.Join(errors.New("写库失败"), errors.New("发通知失败"))
	fmt.Println("合并后的错误:\n" + joined.Error())

	// fmt 的常用动词与 %+v
	u := User{Name: "张三", Age: 18}
	fmt.Printf("%v|%s|%d|%q|%T|%x|%.2f\n", u, u.Name, u.Age, u.Name, u.Age, 255, 9.99)
	fmt.Printf("%%v  %v\n", u)
	fmt.Printf("%%+v %+v\n", u)
}
